new_content = """
export const CHUNK_SIZE = 64;
export function getChunkKey(x, y) {
    const cx = Math.floor(x / CHUNK_SIZE);
    const cy = Math.floor(y / CHUNK_SIZE);
    return `${cx}:${cy}`;
}
export class TerritoryControl {
    territoryMap;
    constructor() {
        this.territoryMap = new Map();
    }
    setOwner(chunkKey, guildId) {
        this.territoryMap.set(chunkKey, guildId);
    }
    getOwner(chunkKey) {
        return this.territoryMap.get(chunkKey);
    }
    removeOwner(chunkKey) {
        this.territoryMap.delete(chunkKey);
    }
    getMap() {
        return this.territoryMap;
    }
    // Static method for NPCRelationshipSystem compatibility
    static applyGuildSovereignty(position) {
        const chunkKey = getChunkKey(position.x, position.y);
        // Return default (neutral territory) since we dont have a territory map
        return { factionId: undefined, influenceLevel: 0 };
    }
}
export function applyGuildSovereignty(npc, territoryMap) {
    const chunkKey = getChunkKey(npc.position.x, npc.position.y);
    const ownerGuildId = territoryMap.get(chunkKey);
    if (ownerGuildId && npc.guildId === ownerGuildId) {
        npc.traits.faith = Number(Math.min(1.0, npc.traits.faith + 0.05).toFixed(4));
        npc.traits.aggression = Number(Math.max(0.0, npc.traits.aggression - 0.02).toFixed(4));
    }
}
//# sourceMappingURL=TerritoryControl.js.map
"""
sftp = client.open_sftp()
with sftp.file("/root/opt/areloria/server/dist/modules/guild/TerritoryControl.js", "w") as f:
    f.write(new_content)
sftp.close()
print("Updated TerritoryControl.js with static method")
# Restart PM2
stdin, stdout, stderr = client.exec_command("pm2 restart all && sleep 3 && pm2 list")
print("\\n=== PM2 Status ===")
print(stdout.read().decode())
client.close()
print("DONE!")
'
